    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    # Find connected components of each non-background color.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == col and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        todo.append((ny, nx))
            comps.append((col, cells))

    def shape(cells):
        r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
        return frozenset((r-r0, c-c0) for r, c in cells)

    def dist(a, b):
        return min(abs(r-y) + abs(c-x) for r, c in a for y, x in b)

    # The long L-shaped marker is the non-background component with both
    # a long horizontal and a vertical arm; its color is the replacement.
    marker = None
    for col, cells in comps:
        rs, cs = [r for r, c in cells], [c for r, c in cells]
        if len(cells) >= 5 and len(set(rs)) >= 2 and len(set(cs)) >= 2:
            if max(sum(r == rr for r, c in cells) for rr in set(rs)) >= 4 and max(sum(c == cc for r, c in cells) for cc in set(cs)) >= 2:
                marker = (col, cells)
                break
    if marker is None:
        return [row[:] for row in grid]
    marker_color, marker_cells = marker

    # Find repeated component silhouettes, then recolor the instance nearest
    # the marker to the marker's color.
    groups = {}
    for col, cells in comps:
        if col != marker_color:
            groups.setdefault(shape(cells), []).append((col, cells))
    candidates = []
    for members in groups.values():
        if len(members) >= 2:
            for col, cells in members:
                candidates.append((dist(cells, marker_cells), col, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = min(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
